public void testCreateTagWithTable() throws UserException, IOException {
    String tag1 = "tag1";
    String tag2 = "tag2";
    String tag3 = "tag3";
    // create a new tag: tag1
    // will fail
    CreateOrReplaceTagInfo info = new CreateOrReplaceTagInfo(tag1, true, false, false, TagOptions.EMPTY);
    Assertions.assertThrows(UserException.class, () -> catalog.createOrReplaceTag(dorisTable, info));
    // add some data
    addSomeDataIntoIcebergTable();
    List<Snapshot> snapshots = Lists.newArrayList(icebergTable.snapshots());
    Assertions.assertEquals(1, snapshots.size());
    // create a new tag: tag1
    catalog.createOrReplaceTag(dorisTable, info);
    assertSnapshotRef(icebergTable.refs().get(tag1), icebergTable.currentSnapshot().snapshotId(), false, null, null, null);
    // create an existed tag: tag1
    Assertions.assertThrows(RuntimeException.class, () -> catalog.createOrReplaceTag(dorisTable, info));
    // create an existed tag with replace
    CreateOrReplaceTagInfo info2 = new CreateOrReplaceTagInfo(tag1, true, true, false, TagOptions.EMPTY);
    catalog.createOrReplaceTag(dorisTable, info2);
    assertSnapshotRef(icebergTable.refs().get(tag1), icebergTable.currentSnapshot().snapshotId(), false, null, null, null);
    // create an existed tag with if not exists
    CreateOrReplaceTagInfo info3 = new CreateOrReplaceTagInfo(tag1, true, false, true, TagOptions.EMPTY);
    catalog.createOrReplaceTag(dorisTable, info3);
    assertSnapshotRef(icebergTable.refs().get(tag1), icebergTable.currentSnapshot().snapshotId(), false, null, null, null);
    // add some data
    addSomeDataIntoIcebergTable();
    addSomeDataIntoIcebergTable();
    snapshots = Lists.newArrayList(icebergTable.snapshots());
    Assertions.assertEquals(3, snapshots.size());
    // create new tag: tag2 with snapshotId
    TagOptions tagOps = new TagOptions(Optional.of(snapshots.get(1).snapshotId()), Optional.empty());
    CreateOrReplaceTagInfo info4 = new CreateOrReplaceTagInfo(tag2, true, false, false, tagOps);
    catalog.createOrReplaceTag(dorisTable, info4);
    assertSnapshotRef(icebergTable.refs().get(tag2), snapshots.get(1).snapshotId(), false, null, null, null);
    // update tag2
    TagOptions tagOps2 = new TagOptions(Optional.empty(), Optional.of(2L));
    CreateOrReplaceTagInfo info5 = new CreateOrReplaceTagInfo(tag2, true, true, false, tagOps2);
    catalog.createOrReplaceTag(dorisTable, info5);
    assertSnapshotRef(icebergTable.refs().get(tag2), icebergTable.currentSnapshot().snapshotId(), false, null, null, 2L);
    // create new tag: tag3
    CreateOrReplaceTagInfo info6 = new CreateOrReplaceTagInfo(tag3, true, false, false, tagOps2);
    catalog.createOrReplaceTag(dorisTable, info6);
    assertSnapshotRef(icebergTable.refs().get(tag3), icebergTable.currentSnapshot().snapshotId(), false, null, null, 2L);
    Assertions.assertEquals(4, icebergTable.refs().size());
}

