    // create a new branch: branch1
    CreateOrReplaceBranchInfo branchInfo = new CreateOrReplaceBranchInfo(branch1, true, false, false, BranchOptions.EMPTY);
    catalog.createOrReplaceBranch(dorisTable, branchInfo);
    // create a new tag: tag2
    addSomeDataIntoIcebergTable();
    CreateOrReplaceTagInfo tagInfo2 = new CreateOrReplaceTagInfo(tag2, true, false, false, TagOptions.EMPTY);
    catalog.createOrReplaceTag(dorisTable, tagInfo2);
    // create a new branch: branch2
